			private IEnumerator RaisePlatform()
			{
				PlayMakerFSM roarFSM = FSMUtility.LocateMyFSM(((Component)HeroController.instance).gameObject, "Roar Lock");
				FsmUtil.GetFsmGameObjectVariable(roarFSM, "Roar Object").Value = ((Component)this).gameObject;
				roarFSM.SendEvent("ROAR ENTER");
				GameObject entrance = ((Component)((Component)this).gameObject.transform.parent).gameObject;
				Transform parent = FiveKnights.preloadedGO["ObjRaise"].transform;
				GameCameras.instance.cameraShakeFSM.FsmVariables.FindFsmBool("RumblingMed").Value = true;
				GameObject raiseAud = Object.Instantiate<GameObject>(((Component)parent.Find("Rise Audio")).gameObject);
				raiseAud.SetActive(true);
				Object.Destroy((Object)(object)raiseAud.GetComponent<PlayAudioAndRecycle>());
				((MonoBehaviour)(object)HeroController.instance).PlayAudio(raiseAud.GetComponent<AudioSource>().clip);
				yield return (object)new WaitForSeconds(0.5f);
				GameObject rumble = Object.Instantiate<GameObject>(((Component)parent.Find("Rumble Dust")).gameObject);
				rumble.SetActive(true);
				rumble.transform.position = new Vector3(56.1f, 35.1f);
				ParticleSystem rumblePartic = rumble.GetComponent<ParticleSystem>();
				rumblePartic.Play();
				GameObject rumble2 = Object.Instantiate<GameObject>(((Component)parent.Find("Rumble Dust")).gameObject);
				rumble2.SetActive(true);
				rumble2.transform.position = new Vector3(58.1f, 35.1f);
				ParticleSystem rumblePartic2 = rumble2.GetComponent<ParticleSystem>();
				rumblePartic2.Play();
				Vector3 ddstatEnd = new Vector3(57.19f, 42.88f, 0.2f);
				Vector3 pillarEnd = new Vector3(56.46f, 28.11f, 2.1054f);
				Vector3 ddstatStart = DDStatue.transform.position;
				Vector3 pillarStart = entrance.transform.position;
				float duration = 2.5f;
				float elapsedTime = 0f;
				while (elapsedTime < duration)
				{
					entrance.transform.position = Vector3.Lerp(pillarStart, pillarEnd, elapsedTime / duration);
					DDStatue.transform.position = Vector3.Lerp(ddstatStart, ddstatEnd, elapsedTime / duration);
					elapsedTime += Time.deltaTime;
					yield return (object)new WaitForEndOfFrame();
				}
				entrance.transform.position = pillarEnd;
				DDStatue.transform.position = ddstatEnd;
				GameCameras.instance.cameraShakeFSM.FsmVariables.FindFsmBool("RumblingMed").Value = false;
				rumblePartic.Stop();
				rumblePartic2.Stop();
				GameObject dust = Object.Instantiate<GameObject>(((Component)parent.Find("Rise Dust")).gameObject);
				dust.SetActive(true);
				dust.transform.position = new Vector3(56.1f, 35.1f);
				dust.GetComponent<ParticleSystem>().Play();
				GameObject dust2 = Object.Instantiate<GameObject>(((Component)parent.Find("Rise Dust")).gameObject);
				dust2.SetActive(true);
				dust2.transform.position = new Vector3(59.3f, 35.1f);
				dust2.GetComponent<ParticleSystem>().Play();
				GameObject impactAud = Object.Instantiate<GameObject>(((Component)parent.Find("Impact Audio")).gameObject);
				impactAud.SetActive(true);
				Object.Destroy((Object)(object)impactAud.GetComponent<PlayAudioAndRecycle>());
				((MonoBehaviour)(object)HeroController.instance).PlayAudio(impactAud.GetComponent<AudioSource>().clip);
				SpawnPlatAndCrack();
				yield return (object)new WaitForSeconds(0.3f);
				roarFSM.SendEvent("ROAR EXIT");
				dust.GetComponent<ParticleSystem>().Stop();
				dust2.GetComponent<ParticleSystem>().Stop();
				yield return (object)new WaitForSeconds(2f);
				Object.Destroy((Object)(object)rumble);
				Object.Destroy((Object)(object)rumble2);
				Object.Destroy((Object)(object)impactAud);
				Object.Destroy((Object)(object)raiseAud);
				Object.Destroy((Object)(object)dust);
				Object.Destroy((Object)(object)dust2);
			}

