			{
				string statueStatePD = ((Component)((Component)self).gameObject.transform.parent.parent).GetComponent<BossStatue>().statueStatePD;
				if (statueStatePD.Contains("Isma"))
				{
					StatueControls["Isma"].StartLever(self);
				}
				else if (statueStatePD.Contains("Zemer"))
				{
					StatueControls["Zemer"].StartLever(self);
				}
				else
				{
					orig.Invoke(self, collision);
				}
			}
		}

		private void BossStatueFlashEffect_FlashApex(orig_FlashApex orig, BossStatueFlashEffect self)
		{
			BossStatue field = Mirror.GetField<BossStatueFlashEffect, BossStatue>(self, "parentStatue");
			switch (field.bossScene.sceneName)
			{
			case "gg isma":
				USceneUtil.Find(((Component)field).gameObject, "FakeStatIsma").SetActive(true);
				break;
			case "gg dryya":
				USceneUtil.Find(((Component)field).gameObject, "FakeStatDryya").SetActive(true);
				break;
			case "gg zemer":
				USceneUtil.Find(((Component)field).gameObject, "FakeStatZemer").SetActive(true);
				break;
			case "gg hegemol":
				USceneUtil.Find(((Component)field).gameObject, "FakeStatHegemol").SetActive(true);
				break;
			}
			orig.Invoke(self);
		}

		private void CallMethodProperOnEnter(orig_OnEnter orig, CallMethodProper self)
		{
			if (((FsmStateAction)self).Fsm.Name == "inspect_region" && ((Object)((FsmStateAction)self).Fsm.GameObject).name == "Inspect_Locked" && ((FsmStateAction)self).State.Name == "Read")
			{
				switch (((Component)((FsmStateAction)self).Fsm.GameObject.transform.parent).gameObject.GetComponent<BossStatue>().bossScene.sceneName)
				{
				case "gg isma":
					((FsmStateAction)self).Fsm.Variables.FindFsmString("Game Text Convo").Value = "ISMA_LOCKED_DESC";
					break;
				case "gg dryya":
					((FsmStateAction)self).Fsm.Variables.FindFsmString("Game Text Convo").Value = "DRYYA_LOCKED_DESC";
					break;
				case "gg zemer":
					((FsmStateAction)self).Fsm.Variables.FindFsmString("Game Text Convo").Value = "ZEM_LOCKED_DESC";
					break;
				case "gg hegemol":
					((FsmStateAction)self).Fsm.Variables.FindFsmString("Game Text Convo").Value = "HEG_LOCKED_DESC";
					break;
				}
			}
			orig.Invoke(self);
		}

