				break;
			case "dryya":
				saveSettings.gotCharms[0] = true;
				saveSettings.newCharms[0] = true;
				break;
			case "zemer":
				saveSettings.gotCharms[1] = true;
				saveSettings.newCharms[1] = true;
				break;
			case "hegemol":
				saveSettings.gotCharms[2] = true;
				saveSettings.newCharms[2] = true;
