		private IEnumerator AnimCoroutine(GameObject CharmAnim, int charmNumber, string boss, string audioName)
		{
			switch (boss)
			{
			case "zemer":
			case "hegemol":
				((MonoBehaviour)(object)this).PlayAudio(_charmUnlock.LoadAsset<AudioClip>(audioName));
				yield return (object)new WaitForSeconds(1.5f);
				break;
			case "dryya":
				((MonoBehaviour)(object)this).PlayAudio(_charmUnlock.LoadAsset<AudioClip>("spell_information_screen"));
				yield return (object)new WaitForSeconds(1.5f);
				((MonoBehaviour)(object)this).PlayAudio(_charmUnlock.LoadAsset<AudioClip>(audioName));
				break;
			case "isma":
				yield return (object)new WaitForSeconds(1.5f);
				CharmAnim.SetActive(true);
				((Renderer)CharmAnim.GetComponent<SpriteRenderer>()).enabled = true;
				((MonoBehaviour)(object)this).PlayAudio(_charmUnlock.LoadAsset<AudioClip>("new_heartpiece_puzzle_bit"));
				yield return (object)new WaitForSeconds(0.5f);
				((MonoBehaviour)(object)this).PlayAudio(_charmUnlock.LoadAsset<AudioClip>(audioName), 1.5f);
				break;
			case "bloom":
				yield return (object)new WaitForSeconds(1.5f);
				((MonoBehaviour)(object)this).PlayAudio(_charmUnlock.LoadAsset<AudioClip>(audioName));
				break;
			}
			CharmAnim.SetActive(true);
			((Renderer)CharmAnim.GetComponent<SpriteRenderer>()).enabled = true;
			yield return (object)new WaitUntil((Func<bool>)(() => ((FsmStateAction)FsmUtil.GetAction<SendEventByName>(FSMUtility.LocateMyFSM(_charmGet, "Msg Control").GetState("Down"))).Finished));
			((Behaviour)CharmAnim.GetComponent<FadeOut>()).enabled = true;
			yield return (object)new WaitForSeconds(1.2f);
			if (boss == "isma")
			{
				PlayerData.instance.gotCharm_10 = true;
				((FullSettingsMod<SaveModSettings, GlobalModSettings>)FiveKnights.Instance).SaveSettings.upgradedCharm_10 = true;
				PlayerData.instance.newCharm_10 = true;
			}
			else
			{
				((FullSettingsMod<SaveModSettings, GlobalModSettings>)FiveKnights.Instance).SaveSettings.gotCharms[charmNumber] = true;
				((FullSettingsMod<SaveModSettings, GlobalModSettings>)FiveKnights.Instance).SaveSettings.newCharms[charmNumber] = true;
			}
			HeroController.instance.AcceptInput();
			HeroController.instance.RegainControl();
			pauseShroom = false;
		}

