			((MonoBehaviour)GameManager.instance).StartCoroutine(WaitForTitle());
			PlantChanger();
			GSPImport.AddFastDashPredicate((Scene prev, Scene next) => ((Scene)(ref next)).name == "White_Palace_09" && ((Scene)(ref prev)).name != "White_Palace_13");
			GSPImport.AddInfiniteChallengeReturnScenePredicate(delegate(SceneLoadInfo info)
			{
				bool flag;
				switch (GameManager.instance.sceneName)
				{
				case "GG_White_Defender":
				case "gg dryya":
				case "gg zemer":
				case "gg hegemol":
				case "gg isma":
					flag = true;
					break;
				default:
					flag = false;
					break;
				}
				return flag && info.SceneName == "White_Palace_09";
			});
			if (!FullSettingsMod<SaveModSettings, GlobalModSettings>.GlobalSettings.ForcedMenuTheme)
			{
				FullSettingsMod<SaveModSettings, GlobalModSettings>.GlobalSettings.ForcedMenuTheme = true;
				MenuStyle item = MenuStyles.Instance.styles.First((MenuStyle x) => ((Object)x.styleObject).name.Contains("Pale_Court"));
				MenuStyles.Instance.SetStyle(MenuStyles.Instance.styles.ToList().IndexOf(item), false, true);
			}
			((Loggable)this).Log("Initializing");
		}

