		private static string GetDreamKey(string name)
		{
			if (((FullSettingsMod<SaveModSettings, GlobalModSettings>)FiveKnights.Instance).SaveSettings.ChampionsCallClears <= 0)
			{
				return "RR_DRYYA_CHEATER";
			}
			string arg = "THIRD";
			if (((FullSettingsMod<SaveModSettings, GlobalModSettings>)FiveKnights.Instance).SaveSettings.ChampionsCallClears == 1)
			{
				arg = "FIRST";
			}
			else if (((FullSettingsMod<SaveModSettings, GlobalModSettings>)FiveKnights.Instance).SaveSettings.ChampionsCallClears == 2)
			{
				arg = "SECOND";
			}
			return $"RR_{name}_{arg}_DREAM";
		}

