					Clip.Shoot => TisoAud["AudTisoShoot"], 
					Clip.Spin => TisoAud["AudTisoSpin"], 
					Clip.ThrowShield => TisoAud["AudTisoThrowShield"], 
					Clip.Walk => TisoAud["AudTisoWalk"], 
