				if (list.Count <= 1)
				{
					_counter = _counter.ToDictionary((KeyValuePair<string, int> kvp) => kvp.Key, (KeyValuePair<string, int> _) => 0);
					text = list[Random.Range(0, list.Count)];
				}
				_counter[text]++;
				return text;
			}
		}
