			private float amount;

			private float t;

			private float timeUp;

			private float stayTime;

			private float timeDown;

			private float flashTimer;

			private bool flashing;

			private FlashState flashingState;

			private float amountCurrent;

			private static readonly int FlashAmount = Shader.PropertyToID("_FlashAmount");

			private SpriteRenderer _sr;

			private void Start()
			{
				_sr = ((Component)this).GetComponent<SpriteRenderer>();
				((Renderer)_sr).material = FiveKnights.Materials["flash"];
				PolygonCollider2D[] componentsInChildren = ((Component)((Component)this).transform).GetComponentsInChildren<PolygonCollider2D>(true);
				for (int i = 0; i < componentsInChildren.Length; i++)
				{
