			private IEnumerator WaitForInitFinish(PlayMakerFSM fsm1, PlayMakerFSM fsm2)
			{
				string stopState = "Idle Anim";
				yield return (object)new WaitUntil((Func<bool>)(() => _hasP2GulkaInit));
				while ((Object)(object)fsm1 != (Object)null && (Object)(object)fsm2 != (Object)null)
				{
					PlayMakerFSM obj = fsm1;
					PlayMakerFSM obj2 = fsm2;
					bool enabled = true;
					((Behaviour)obj2).enabled = true;
					((Behaviour)obj).enabled = enabled;
					fsm1.SetState("Shoot Antic");
					fsm2.SetState("Shoot Antic");
					yield return (object)new WaitUntil((Func<bool>)(() => fsm1.ActiveStateName == stopState || fsm2.ActiveStateName == stopState));
					if (fsm1.ActiveStateName == stopState)
					{
						((Behaviour)fsm1).enabled = false;
						((Component)fsm1).GetComponent<tk2dSpriteAnimator>().Play("Idle");
						yield return (object)new WaitUntil((Func<bool>)(() => fsm2.ActiveStateName == stopState));
						((Behaviour)fsm2).enabled = false;
						((Component)fsm2).GetComponent<tk2dSpriteAnimator>().Play("Idle");
					}
					else
					{
						((Behaviour)fsm2).enabled = false;
						((Component)fsm2).GetComponent<tk2dSpriteAnimator>().Play("Idle");
						yield return (object)new WaitUntil((Func<bool>)(() => fsm1.ActiveStateName == stopState));
						((Behaviour)fsm1).enabled = false;
						((Component)fsm1).GetComponent<tk2dSpriteAnimator>().Play("Idle");
					}
					yield return (object)new WaitForSeconds(2f + 0.1f * (float)Random.Range(0, 4));
				}
			}

			private IEnumerator Phase2Spawn(GameObject go, GameObject turret)
			{
				Vector2 pos = Vector2.op_Implicit(go.transform.position);
				yield return (object)new WaitForSeconds(2f);
				GameObject gulk = Object.Instantiate<GameObject>(FiveKnights.preloadedGO["Gulka"]);
				((Object)gulk).name = "SpecialEnemy";
				Animator anim = gulk.GetComponent<Animator>();
				float num = 180f;
				Extensions.SetPosition2D(gulk.transform, pos);
				Transform transform = gulk.transform;
				transform.localScale *= 1.4f;
				Extensions.SetRotation2D(gulk.transform, num);
				GameObject obj = Object.Instantiate<GameObject>(FiveKnights.preloadedGO["Seal"], gulk.transform.position + Vector3.down, Quaternion.identity);
				obj.transform.localScale = new Vector3(2f, 2f, 1f);
				obj.layer = 19;
				obj.AddComponent<GulkaSeal>();
				HealthManager component = turret.GetComponent<HealthManager>();
				RemoveGeo(component);
				((Object)turret).name = "SpecialEnemy";
				MeshRenderer mesh = turret.GetComponent<MeshRenderer>();
				PlayMakerFSM fsm = FSMUtility.LocateMyFSM(turret, "Plant Turret");
				GameObject value = fsm.GetAction<CreateObject>("Fire", 3).gameObject.Value;
				if (!Object.op_Implicit((Object)(object)value.GetComponent<ModifiedSpit>()))
				{
					value.AddComponent<ModifiedSpit>();
				}
				fsm.GetAction<SetInvincible>("Wake", 2).Invincible = FsmBool.op_Implicit(true);
				component.IsInvincible = true;
				((Renderer)mesh).enabled = false;
				List<MeshRenderer> lst = new List<MeshRenderer>();
				MeshRenderer[] componentsInChildren = turret.GetComponentsInChildren<MeshRenderer>(true);
				foreach (MeshRenderer val in componentsInChildren)
				{
					((Renderer)val).enabled = false;
					lst.Add(val);
				}
				fsm.FsmVariables.FindFsmFloat("Distance Max").Value = 50f;
				fsm.GetAction<Wait>("Idle Anim", 1).time = FsmFloat.op_Implicit(1.5f);
				Extensions.SetRotation2D(turret.transform, num);
				turret.SetActive(true);
				num *= (float)Math.PI / 180f;
				Extensions.SetPosition2D(turret.transform, pos.x - 0.5f * Mathf.Sin(num), pos.y + 0.5f * Mathf.Cos(num));
				anim.Play("SpawnGulka");
				yield return (object)new WaitForSeconds(0.05f);
				yield return (object)new WaitWhile((Func<bool>)(() => anim.IsPlaying()));
				Object.Destroy((Object)(object)gulk);
				((Renderer)mesh).enabled = true;
				foreach (MeshRenderer item in lst)
				{
					((Renderer)item).enabled = true;
				}
				fsm.SendEvent("SEE HERO");
				((Behaviour)fsm).enabled = false;
				_hasP2GulkaInit = true;
				((MonoBehaviour)this).StartCoroutine(FinalGulkaKiller(turret));
			}

