			private IEnumerator AttackChoice()
			{
				yield return WaitToAttack();
				yield return (object)new WaitForSeconds(Random.Range(0.5f, 0.8f) + offsetTime);
				_prev = SeedBomb;
				_prev();
				while (true)
				{
					yield return (object)new WaitWhile((Func<bool>)(() => _attacking));
					yield return (object)new WaitForSeconds(Random.Range(0.5f, 0.8f) + offsetTime);
					_attacking = true;
					if (spawningWalls)
					{
						Log("Using Seed Bomb and spawning walls");
						_prev = SeedBomb;
						_prev();
						if (!usedAgony)
						{
							yield return (object)new WaitWhile((Func<bool>)(() => _attacking));
							yield return (object)new WaitForSeconds(Random.Range(0.5f, 0.8f) + offsetTime);
							_attacking = true;
							Log("Doing Agony");
							((MonoBehaviour)this).StartCoroutine(Agony());
						}
						continue;
					}
					if (startedIsmaDeath)
					{
						break;
					}
					int[] array = new int[3] { 0, 2, 2 };
					Action[] array2 = new Action[3] { SeedBomb, AirFist, WhipAttack };
					if (!_wallActive)
					{
						array[0] += Math.Max(3 - EnemyPlantSpawn.FoolCount - 1, 0);
						array[0] += 2 - EnemyPlantSpawn.TurretCount;
					}
					else
					{
						array[0] += 3 - EnemyPlantSpawn.PillarCount;
					}
					if (_prev.Method.Name == "SeedBomb")
					{
						array[0]--;
						array[1]++;
					}
					if (_prev.Method.Name == "AirFist")
					{
						array[1]--;
					}
					if (_prev.Method.Name == "WhipAttack")
					{
						array[2]--;
					}
					List<Action> list = new List<Action>();
					for (int num = 0; num < array.Length; num++)
					{
						for (int num2 = 0; num2 < array[num]; num2++)
						{
							list.Add(array2[num]);
						}
					}
					_prev = list[Random.Range(0, list.Count)];
					Log("Doing: " + _prev.Method.Name);
					_prev();
				}
				((MonoBehaviour)this).StartCoroutine(IsmaLoneDeath());
			}

			private IEnumerator DuoAttacks()
			{
				EnemyPlantSpawn.isPhase2 = true;
				_ddFsm.GetAction<SendEventByName>("After Throw?", 0).delay = FsmFloat.op_Implicit(0.2f);
				_ddFsm.InsertAction("After Throw?", (FsmStateAction)(object)_ddFsm.GetAction<Tk2dPlayAnimation>("Idle", 0), 0);
				FsmUtil.InsertMethod(_ddFsm, "Throw 1", (Action)delegate
				{
					((Object)_ddFsm.FsmVariables.FindFsmGameObject("Dung Ball").Value).name = "Ogrim Thrown Ball";
				}, 2);
				_ddFsm.GetAction<Wait>("G Slam Recover", 0).time = FsmFloat.op_Implicit(1.2f);
				FsmUtil.CopyFsmState(_ddFsm, "G Slam Recover", "G Slam Recover Acid");
				_ddFsm.GetAction<Wait>("G Slam Recover Acid", 0).time = FsmFloat.op_Implicit(0.5f);
				FsmUtil.RemoveAction(_ddFsm, "G Slam Recover Acid", 1);
				FsmUtil.InsertMethod(_ddFsm, "G Slam Recover Acid", (Action)delegate
				{
					Log("G Slam Recover Acid");
					FsmUtil.ChangeFsmTransition(_ddFsm, "G Slam Recover", "WAIT", "Move Choice");
				}, 0);
				_ddFsm.GetAction<SetFsmBool>("Tunneling R", 0).variableName.Value = "RumblingSmall";
				_ddFsm.GetAction<SetFsmBool>("Erupt Antic", 3).variableName.Value = "RumblingSmall";
				_ddFsm.GetAction<SetFsmBool>("Erupt Antic R", 2).variableName.Value = "RumblingSmall";
				_ddFsm.GetAction<SetFsmBool>("Erupt Out First", 1).variableName.Value = "RumblingSmall";
				_ddFsm.GetAction<SetFsmBool>("Erupt Out", 2).variableName.Value = "RumblingSmall";
				FsmUtil.InsertMethod(_ddFsm, "G Slam Antic", (Action)EvadeBeforeAttack, 0);
				_ddFsm.GetAction<RandomFloat>("Timer", 1).min.Value = 2.1f;
				_ddFsm.GetAction<RandomFloat>("Timer", 1).max.Value = 2.1f;
				_ddFsm.InsertMethod("RJ Launch", 6, delegate
				{
					_ddFsm.FsmVariables.FindFsmFloat("Throw Speed Crt").Value = 12f;
				});
				FsmUtil.InsertMethod(_ddFsm, "Ball Hit Up", (Action)delegate
				{
					FsmInt obj = _ddFsm.FsmVariables.FindFsmInt("Bounces");
					int value = obj.Value;
					obj.Value = value - 1;
				}, 0);
				_ddFsm.InsertCoroutine("RJ In Air", 8, CheckPos);
				((MonoBehaviour)this).StartCoroutine(DungStrike());
				FsmUtil.InsertMethod(_ddFsm, "Timer", (Action)delegate
				{
					if (!startedIsmaRage)
					{
						((MonoBehaviour)this).StartCoroutine(WaitForWhipOrBomb());
					}
				}, 0);
				FsmUtil.InsertMethod(_ddFsm, "RJ Launch", (Action)delegate
				{
					((MonoBehaviour)this).StartCoroutine(WaitForBomb());
				}, 0);
				FsmUtil.InsertMethod(_ddFsm, "G Slam", (Action)delegate
				{
					((MonoBehaviour)this).StartCoroutine(WaitForAirFist());
				}, 0);
				yield return (object)new WaitUntil((Func<bool>)(() => _wallActive));
				_ddFsm.GetAction<Wait>("AD In", 0).time.Value = 0.4f;
				FsmUtil.RemoveAction(_ddFsm, "RJ Launch", 0);
				FsmUtil.InsertMethod(_ddFsm, "RJ Launch", (Action)delegate
				{
					_usingThornPillars = false;
					((MonoBehaviour)this).StartCoroutine(WaitForThornPillars());
				}, 0);
				FsmUtil.InsertMethod(_ddFsm, "RJ Speed Adjust", (Action)delegate
				{
					_usingThornPillars = true;
				}, 0);
				((MonoBehaviour)this).StartCoroutine(OgrimStrike());
				FsmUtil.InsertMethod(_ddFsm, "Under", (Action)delegate
				{
					((MonoBehaviour)this).StartCoroutine(WaitForAgony());
				}, 0);
				IEnumerator CheckPos()
				{
					yield return (object)new WaitUntil((Func<bool>)delegate
					{
						//IL_0044: Unknown result type (might be due to invalid IL or missing references)
						//IL_0065: Unknown result type (might be due to invalid IL or missing references)
						return (!_ddFsm.FsmVariables.FindFsmBool("Still Bouncing").Value && _ddFsm.FsmVariables.FindFsmBool("Air Dive Height").Value) || (FastApproximately(dd.transform.position.y, 13.5f, 0.75f) && _rbDD.velocity.y > 0f && _ddFsm.FsmVariables.FindFsmInt("Bounces").Value < -3) || startedIsmaRage;
					});
					_ddFsm.SendEvent("AIR DIVE");
				}
				void EvadeBeforeAttack()
				{
					if (!_ogrimEvaded && _wallActive && (FastApproximately(Extensions.GetPositionX(dd.transform), MiddleX, 4f) || (Extensions.GetPositionX(dd.transform) < MiddleX - 4f && Extensions.GetPositionX(dd.transform) - Extensions.GetPositionX(_target.transform) > 0f) || (Extensions.GetPositionX(dd.transform) > MiddleX + 4f && Extensions.GetPositionX(dd.transform) - Extensions.GetPositionX(_target.transform) < 0f)))
					{
						_ddFsm.SetState("Evade Dir");
						_ddFsm.GetAction<SendRandomEvent>("After Evade", 0).weights[0].Value = 0f;
						_ogrimEvaded = true;
					}
					else
					{
						_ddFsm.GetAction<SendRandomEvent>("After Evade", 0).weights[0].Value = 0.5f;
						_ogrimEvaded = false;
					}
				}
				IEnumerator WaitForAgony()
				{
					yield return (object)new WaitForSeconds(0.6f);
					yield return WaitToAttack();
					yield return Agony();
				}
				IEnumerator WaitForAirFist()
				{
					yield return WaitToAttack();
					AirFist();
				}
				IEnumerator WaitForBomb()
				{
					yield return WaitToAttack();
					SeedBomb();
				}
				IEnumerator WaitForThornPillars()
				{
					yield return WaitToAttack();
					ThornPillars();
				}
				IEnumerator WaitForWhipOrBomb()
				{
					yield return WaitToAttack();
					if (spawningWalls)
					{
						SeedBomb();
					}
					else
					{
						WhipAttack();
					}
				}
			}

			private IEnumerator SpawnWalls()
			{
				GameObject[] array;
				if (!startedOgrimRage && !startedIsmaRage)
				{
					yield return (object)new WaitWhile((Func<bool>)(() => _healthPool > (onlyIsma ? WallHP : WallHPDuo)));
					if (onlyIsma)
					{
						yield return (object)new WaitWhile((Func<bool>)(() => _attacking));
						Log("Queueing Seed Bomb");
						spawningWalls = true;
						yield return (object)new WaitWhile((Func<bool>)(() => spawningWalls));
						yield return (object)new WaitForSeconds(1f);
						GameObject.Find("SeedFloor").GetComponent<EnemyPlantSpawn>().Phase2Spawn();
					}
					else
					{
						yield return (object)new WaitUntil((Func<bool>)(() => _ddFsm.ActiveStateName == "Idle"));
						FsmUtil.InsertMethod(_ddFsm, "Rage?", (Action)delegate
						{
							_ddFsm.SetState("TD Set");
						}, 0);
						spawningWalls = true;
						yield return (object)new WaitUntil((Func<bool>)(() => _ddFsm.ActiveStateName.Contains("Tunneling")));
						FsmUtil.RemoveAction(_ddFsm, "Rage?", 0);
						yield return (object)new WaitForSeconds(0.3f);
						FSMUtility.LocateMyFSM(dd, "Constrain X").FsmVariables.FindFsmFloat("Edge R").Value = 88f;
						FSMUtility.LocateMyFSM(dd, "Constrain X").FsmVariables.FindFsmFloat("Edge L").Value = 64f;
						_ddFsm.FsmVariables.FindFsmFloat("Dolphin Max X").Value = 88f;
						_ddFsm.FsmVariables.FindFsmFloat("Dolphin Min X").Value = 64f;
						_ddFsm.FsmVariables.FindFsmFloat("Max X").Value = 85f;
						_ddFsm.FsmVariables.FindFsmFloat("Min X").Value = 67f;
						yield return (object)new WaitWhile((Func<bool>)(() => spawningWalls));
						yield return (object)new WaitForSeconds(1f);
					}
					EnemyPlantSpawn.isPhase2 = true;
					killAllMinions = true;
					yield return (object)new WaitForSeconds(0.1f);
					killAllMinions = false;
					_wallActive = true;
					wallR = Object.Instantiate<GameObject>(FiveKnights.preloadedGO["Wall"]);
					wallR.transform.localScale = new Vector3(wallR.transform.localScale.x * -1f, wallR.transform.localScale.y, wallR.transform.localScale.z);
					wallL = Object.Instantiate<GameObject>(FiveKnights.preloadedGO["Wall"]);
					GameObject gameObject = ((Component)wallR.transform.Find("FrontW")).gameObject;
					GameObject gameObject2 = ((Component)wallL.transform.Find("FrontW")).gameObject;
					gameObject.layer = 8;
					gameObject2.layer = 8;
					wallR.transform.position = new Vector3(RightX - 2.5f, GroundY, 0.1f);
					wallL.transform.position = new Vector3(LeftX + 2.5f, GroundY, 0.1f);
					Animator anim = gameObject.GetComponent<Animator>();
					((MonoBehaviour)(object)this).PlayAudio(FiveKnights.Clips["IsmaAudWallGrow"]);
					yield return (object)new WaitWhile((Func<bool>)(() => anim.GetCurrentFrame() < 3));
					((Component)wallR.transform.Find("Petal")).gameObject.SetActive(true);
					((Component)wallL.transform.Find("Petal")).gameObject.SetActive(true);
					Vector2 val = Vector2.op_Implicit(_target.transform.position);
					if (val.x > RightX - 6f)
					{
						_target.transform.position = Vector2.op_Implicit(new Vector2(RightX - 6f, val.y));
					}
					else if (val.x < LeftX + 6f)
					{
						_target.transform.position = Vector2.op_Implicit(new Vector2(LeftX + 6f, val.y));
					}
					yield return (object)new WaitWhile((Func<bool>)(() => _healthPool > (onlyIsma ? SpikeHP : SpikeHPDuo)));
					if (onlyIsma)
					{
						yield return (object)new WaitWhile((Func<bool>)(() => _attacking));
						spawningWalls = true;
						yield return (object)new WaitWhile((Func<bool>)(() => spawningWalls));
						yield return (object)new WaitForSeconds(1f);
					}
					else
					{
						yield return (object)new WaitUntil((Func<bool>)(() => _ddFsm.ActiveStateName == "Idle"));
						FsmUtil.InsertMethod(_ddFsm, "Rage?", (Action)delegate
						{
							_ddFsm.SetState("TD Set");
						}, 0);
						spawningWalls = true;
						yield return (object)new WaitUntil((Func<bool>)(() => _ddFsm.ActiveStateName.Contains("Tunneling")));
						FsmUtil.RemoveAction(_ddFsm, "Rage?", 0);
						yield return (object)new WaitForSeconds(0.3f);
						yield return (object)new WaitWhile((Func<bool>)(() => spawningWalls));
						yield return (object)new WaitForSeconds(1f);
					}
					array = (GameObject[])(object)new GameObject[2] { wallR, wallL };
					for (int num = 0; num < array.Length; num++)
					{
						GameObject gameObject3 = ((Component)array[num].transform.Find("Spike")).gameObject;
