			private GameObject LocateBall()
			{
				tk2dSpriteAnimator tk = dd.GetComponent<tk2dSpriteAnimator>();
				GameObject[] array = (from x in Object.FindObjectsOfType<GameObject>()
					where TestBall(x)
					select x).ToArray();
				if (array.Length != 0)
				{
					return array[_rand.Next(0, array.Length)];
				}
				return null;
				bool TestBall(GameObject x)
				{
					//IL_0030: Unknown result type (might be due to invalid IL or missing references)
					if ((Object)(object)x.GetComponent<Rigidbody2D>() == (Object)null)
					{
						return false;
					}
					if (!x.activeSelf || !(Extensions.GetPositionY(x.transform) > 13f) || !(x.GetComponent<Rigidbody2D>().velocity.y > 0f))
					{
						return false;
					}
					if (tk.CurrentClip.name.Contains("Throw") && ((Object)x).name.Contains("Ogrim Thrown Ball"))
					{
						return true;
					}
					if (tk.CurrentClip.name.Contains("Erupt") && ((Object)x).name.Contains("Dung Ball") && (Object)(object)x.GetComponent<DungTracker>() == (Object)null && _ddFsm.FsmVariables.FindFsmInt("Rages").Value > 0 && FastApproximately(Extensions.GetPositionX(x.transform), Extensions.GetPositionX(_target.transform), 7.5f))
					{
						return true;
					}
					return false;
				}
			}

