					{
						flashTimer += Time.deltaTime;
						t = flashTimer / timeUp;
						amountCurrent = Mathf.Lerp(0f, amount, t);
						((Renderer)_currSR).material.SetFloat(FlashAmount, amountCurrent);
					}
					else
					{
						((Renderer)_currSR).material.SetFloat(FlashAmount, amount);
						flashTimer = 0f;
						flashing = false;
						flashingState = FlashState.Stay;
					}
				}
				if (flashingState == FlashState.Stay)
				{
					if (flashTimer < stayTime)
					{
						flashTimer += Time.deltaTime;
					}
					else
