					prevAtt = currAtt;
					int[] array = new int[6];
					List<Func<IEnumerator>> list = new List<Func<IEnumerator>> { Jump, Slam, Dig, Charge, MightySlam, MightyDig };
					float num = Math.Abs(((Component)this).transform.position.x - ((((Component)this).transform.localScale.x > 0f) ? RightX : LeftX));
					array[0] += 2;
					if (num < Width / 3f + 2f)
					{
						array[3] += 4;
						if (phase > 1)
						{
							array[4] += 2;
						}
						if (phase > 2)
						{
							array[5] += 2;
						}
					}
					else if (num < 2f * Width / 2f)
					{
						array[1]++;
						array[2]++;
						array[3]++;
						if (phase > 1)
						{
							array[4]++;
						}
						if (phase > 2)
						{
							array[5]++;
						}
					}
					else
					{
						array[1] += 2;
						array[2] += 2;
						if (phase > 1)
						{
							array[4]++;
						}
						if (phase > 2)
						{
							array[5]++;
						}
					}
					if (prevAtt != null)
					{
						array[list.IndexOf(prevAtt)] = 0;
						if (prevAtt == new Func<IEnumerator>(Jump))
						{
							array[4] = 0;
							array[5] = 0;
							if (prevAtt2 != null && prevAtt2 == new Func<IEnumerator>(Dig))
							{
								array[1]++;
							}
						}
						if (prevAtt == new Func<IEnumerator>(Dig))
						{
							array[1] = 0;
						}
					}
					if (prevAtt2 != null)
					{
						array[list.IndexOf(prevAtt2)]--;
					}
					List<Func<IEnumerator>> list2 = new List<Func<IEnumerator>>();
					for (int num2 = 0; num2 < array.Length; num2++)
					{
						for (int num3 = 0; num3 < array[num2]; num3++)
						{
							list2.Add(list[num2]);
						}
					}
					currAtt = list2[Random.Range(0, list2.Count)];
					Log("[Attack] " + currAtt.Method.Name);
					((MonoBehaviour)this).StartCoroutine(currAtt());
				}
			}

