		public class ElegyBeam : MonoBehaviour
		{
			public GameObject parent;

			public Vector2 offset;

			public bool activate;

			private Animator _anim;

			private float PosY = (OWArenaFinder.IsInOverWorld ? 100.5f : 10f);

			private void Awake()
			{
				((Component)this).gameObject.layer = 22;
				DamageHero obj = ((Component)this).gameObject.AddComponent<DamageHero>();
				obj.damageDealt = 1;
				obj.hazardType = 1;
				obj.shadowDashHazard = false;
				_anim = ((Component)this).GetComponent<Animator>();
			}

			private void OnEnable()
			{
				((MonoBehaviour)GameManager.instance).StartCoroutine(Beam());
			}

			private IEnumerator Beam()
			{
				Vector2 val = default(Vector2);
				((Vector2)(ref val))..ctor(((Component)HeroController.instance).transform.position.x, PosY);
				Quaternion val2 = Quaternion.Euler(0f, 0f, Mathf.Sign(((Component)this).transform.localScale.x) * (float)Random.Range(15, 105));
				((Component)this).gameObject.transform.SetPositionAndRotation(Vector2.op_Implicit(val + offset), val2);
				_anim.Play("Beams");
				yield return (object)new WaitWhile((Func<bool>)(() => _anim.GetCurrentFrame() < 3));
				((Behaviour)_anim).enabled = false;
				yield return (object)new WaitUntil((Func<bool>)(() => activate));
				yield return (object)new WaitForSeconds(0.1f);
				((Behaviour)_anim).enabled = true;
				yield return (object)new WaitWhile((Func<bool>)(() => _anim.GetCurrentFrame() < 9));
				((Behaviour)_anim).enabled = false;
				yield return (object)new WaitForSeconds(0.17f);
				((Behaviour)_anim).enabled = true;
				Object.Destroy((Object)(object)((Component)this).GetComponent<PolygonCollider2D>());
				Object.Destroy((Object)(object)((Component)this).GetComponent<DamageHero>());
				yield return (object)new WaitWhile((Func<bool>)(() => _anim.IsPlaying("Beams")));
				Object.Destroy((Object)(object)((Component)this).gameObject);
			}
		}
	}
